			function saveWorker() {
			    
			    var dmWorker = app.lookup("dmWorker");
			    
			    dmWorker.setValue("ATFINO", atfino);
			    
			    // 추가정보 5개 시스템에 대한 validation 체크
			    //var dsEffeSystem = app.lookup("dsEffeSystem");
			    var dsAplyInstList= app.lookup("dsAplyInstList");
			    var dsCnterEnfsnInfo = app.lookup("dsCnterEnfsnInfo");
			    var dmCnterEnfsnInfo = app.lookup("dmCnterEnfsnInfo");
			    var columns = dsCnterEnfsnInfo.getColumnNames();
			    
			    for (var l = 0; l < columns.length; l++) {
			        dsCnterEnfsnInfo.setValue(0, columns[l], dmCnterEnfsnInfo.getValue(columns[l]));
			    }
			    
			    if (dsAplyInstList.getRowCount() > 0) { // 추가정보 5개 시스템에 권한이 있는 경우
			        
			        dsCnterEnfsnInfo.clearFilter();
			        var validation = false;
			        for (var i = 0; i < dsCnterEnfsnInfo.getRowCount(); i++) {
			            for (var j = 0; j < columns.length; j++) {
			                if (columns[j] != "ENFSN_NO" && columns[j] != "CNTER_INST_NO" && columns[j] != "CNTER_INST_NM" && columns[j] != "CNTER_PRECON_UNT_TASKWK_SE_CD") {
			                    if (dsCnterEnfsnInfo.getValue(i, columns[j]) != "") { // 사용자가 입력한 데이터가 있음
			                        validation = true;
			                    }
			                }
			            }
			            if (validation) {
			                if(dsCnterEnfsnInfo.getValue(i, "FTE_YN") == "" || dsCnterEnfsnInfo.getValue(i, "FT_YN") == "" ){
			                    var untTaskWkNm = ""; // 단위업무시스템 명
			                    for(var k = 0; k < dsAplyInstList.getRowCount(); k++){
			                        if(dsCnterEnfsnInfo.getValue(i, "CNTER_INST_NO") == dsAplyInstList.getValue(k, "INST_NO")){
			                            untTaskWkNm = dsAplyInstList.getValue(k, "INST_NM");
			                            validation = false;
			                            var alertMsg = untTaskWkNm+"의 상근여부와 전임여부를 선택하세요."
			                            util.Msg.alert(app, alertMsg);
			                            return;
			                        }
			                    }
			                } else {
			                    validation = false;
			                }
			                if(ValueUtil.isNull(dsCnterEnfsnInfo.getValue(i, "CNTER_PRECON_UNT_TASKWK_SE_CD"))){
			                    var fInstNo = dsCnterEnfsnInfo.getValue(i, "CNTER_INST_NO");
			                    var fRow = dsAplyInstList.findFirstRow("INST_NO == '" + fInstNo + "'").getIndex();
			                    dsCnterEnfsnInfo.setValue(i, "CNTER_PRECON_UNT_TASKWK_SE_CD", dsAplyInstList.getValue(fRow, "UNT_TASKWK_SE_CD"));
			                }
			            } else {
			                dsCnterEnfsnInfo.deleteRow(i);
			                dsCnterEnfsnInfo.commit();
			            }
			        }
			    }

			    datasetFilter();
			    // 추가정보 5개 시스템에 대한 validation 체크 끝
			    
			    var subSave = app.lookup("subSave");
			    if (app.lookup("btn6").value == "저장") {
			        subSave.action = "/isry/itgcm/sysmgmt/userjoin/saveWorker.do";
			    }
			    
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            //var subCheck = app.lookup("subCheck");
			            //var appId = subCheck.getMetadata("uri");
			            //var msg = subCheck.getMetadata("msg");
			            
			            //if (msg != null) {
			                //alert(msg);
			            //} else {

			            var dmMemberInfoCheck = app.lookup("dmMemberInfoCheck");
			            
			            //alert(dmMemberInfoCheck.getValue("resultStr"));
			            
			            if (dmMemberInfoCheck != null && dmMemberInfoCheck.getValue("resultStr") != null && dmMemberInfoCheck.getValue("resultStr") != "") {
			                util.Msg.alert(app, dmMemberInfoCheck.getValue("resultStr"));
			            } else {
			                
			                /* 화면조회용 셋팅*/
			                app.lookup("dmEnfsnNo").setValue("enfsnNo"       , app.lookup("subSave").getMetadata("ENFSN_NO"));
			                app.lookup("dmEnfsnNo").setValue("userId"        , app.lookup("subSave").getMetadata("USER_ID"));
			                app.lookup("dmEnfsnNo").setValue("INDV_IDNTFC_NO", app.lookup("subSave").getMetadata("INDV_IDNTFC_NO"));
			                
			                var grp6 = app.lookup("grp6");
			                grp6.visible = true;
			                
			                if (app.lookup("btn6").value == "저장") {
			                    
			                    //util.Msg.alert(app, "저장되었습니다.");
			                    util.Msg.alert(app, "저장되었습니다.", null, function() {
			                        app.close();
			                    });
			                    
			                    if(msCrudType == "CREATE"){
			                        
			                    }
			                    
			                    
			                } else {
			                    util.Msg.alert(app, "수정되었습니다.");
			                }
			                
			                test1 = false;
			                test2 = false;
			                
			                /* 화면조회*/
			                //subWorker();
			                onBodyLoad();  
			            }
			        }
			    });
			}



