			/*
			 * dmCnterEnfsnInfo을 dsCnterEnfsnInfo에 담는다
			 */
			function datamapToDataist(){
			    var dsCnterEnfsnInfo = app.lookup("dsCnterEnfsnInfo");
			    var dmCnterEnfsnInfo = app.lookup("dmCnterEnfsnInfo");
			    dsCnterEnfsnInfo.clearFilter();
			    var fInstNo = dmCnterEnfsnInfo.getValue("CNTER_INST_NO");
			    var fRow = dsCnterEnfsnInfo.findFirstRow("CNTER_INST_NO == '" + fInstNo + "'").getIndex();
			    var colNames = dsCnterEnfsnInfo.getColumnNames();
			    for(var i = 0; i < colNames.length; i++){
			        var colName = colNames[i];
			        dsCnterEnfsnInfo.setValue(fRow, colName, dmCnterEnfsnInfo.getValue(colName));
			    }
			    datasetFilter();
			}

