			function setDept(orgCode, deptCmd, deptEtcText){
			    
			    console.log("setDept();");
			    
			    // 기관을 선택할 때 해당 부서 목록을 가져온다.
			    var dmOrgCode = app.lookup("dmOrg");
			    dmOrgCode.setValue("orgCode", orgCode);

			    var deptCd   = app.lookup("dmWorker").getValue("OGDP_DEPT_CD");   /* 조회한 부서코드*/
			    var deptCdNm = app.lookup("dmWorker").getValue("OGDP_DEPT_NM");   /* 조회한 부서코드*/
			    
			    var prvuseJoinYn = app.lookup("dmWorker").getValue("PRVUSE_JOIN_SCRIN_YN"); /* 조회한 전용가입엽우*/
			    var dsOrgDept = app.lookup("dsOrgDept");
			    dsOrgDept.clearData();

			    util.Submit.send(app, "subSelectDept", function(pbSuccess) {
			        if (pbSuccess) {

			            var insertRow = dsOrgDept.insertRow(dsOrgDept.getRowCount() == 0 ? 0 : dsOrgDept.getRowCount() - 1);
			            var newRowData = {
			                "INST_NO": dmOrgCode,
			                "DEPT_CD": "000",
			                "DEPT_NM": "- 기타 (직접입력) -"
			            };
			            insertRow.setRowData(newRowData);
			            if(dsOrgDept.getRowCount() == 1){
			                app.lookup(deptCmd).value = '000';
			                app.lookup(deptCmd).visible = false;
			                app.lookup('grp48').getLayout().setColumnVisible(0, false);
			                app.lookup('grp48').getLayout().setColumnVisible(1, true);
			                app.lookup('grp63').getLayout().setColumnVisible(0, false);
			                app.lookup('grp63').getLayout().setColumnVisible(1, true);
			//                app.lookup(deptEtcText).value = '';
			                app.lookup(deptEtcText).visible = true; 
			            }else{
			                
			                app.lookup(deptCmd).value = '';
			                app.lookup(deptCmd).visible = true;
			                app.lookup('grp48').getLayout().setColumnVisible(0, true);
			                app.lookup('grp48').getLayout().setColumnVisible(1, false);
			                app.lookup('grp63').getLayout().setColumnVisible(0, true);
			                app.lookup('grp63').getLayout().setColumnVisible(1, false);
			                app.lookup(deptEtcText).value = '';
			                app.lookup(deptEtcText).visible = false;    
			            }
			            
			            if(msCrudType == "CREATE"){
			                app.lookup("cmb19").enabled = true;
			            }
			            
			            /* 소속부서 셋팅 종사자관리수정(UPDATE) 또는 내정보수정시(myInfoUpdate)*/
			            if(msCrudType == "UPDATE"){
			//                console.log("=== 소속부서 셋팅 ===");
			                util.DataMap.setValue(app, "dmWorker", "OGDP_DEPT_CD", deptCd);
			                util.DataMap.setValue(app, "dmWorker", "OGDP_DEPT_NM", deptCdNm);
			                
			                if(prvuseJoinYn == 'N'){
			                    /* 종사자*/
			                    formRowVisible_fn("grp48", "cmb19", "ipb3");
			                }                
			                if(prvuseJoinYn == 'Y'){
			                    /* 기관*/
			                    formRowVisible_fn("grp63", "cmb47", "ipb48");
			                }
			            }
			            
			            util.Control.redraw(app, ['grp48', 'grp63']);
			        }
			    });
			}

