			/*
			 * "권한취소" 버튼(btn25)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtn25Click(e){
			    var btn25 = e.control;
			    
			    var vsMessage = "해당 종사자의 권한이 초기화 됩니다.\n\r초기화하시겠습니까?";
			    
			    util.Msg.confirm(app, vsMessage, null, function(){
			        /*확인버튼 콜백*/
			        var psUserId = util.DataMap.getValue(app, "dmWorker", "USER_ID");
			        if (ValueUtil.isNull(psUserId)) {
			            var initValue = app.getHostProperty("initValue");
			            psUserId = initValue["USER_ID"];
			            if (ValueUtil.isNull(psUserId)) {
			                alert("종사자의 사용자아이디 정보가 없습니다!");
			                return;
			            }   
			        }
			        
			        util.DataMap.setValue(app, "dmAuthrtReset", "USER_ID", psUserId);
			        util.Submit.send(app, "subAuthrtReset", function(pbSuccess) {
			            if (pbSuccess) {
			                util.Msg.alert(app, "권한이 초기화 처리 되었습니다.", null, function() {
			                    app.close();
			                });
			            }
			        });
			        
			    }, function(){
			         /*취소버튼 콜백*/
			    }, "경고", null, true);
			}

